import type { Directory, User } from "./types.ts";

export function grantsFor(user: User, directory: Directory): Set<string> {
  // ACCESS-284: Directory entries are not always flattened (e.g. auditor -> report-reader), so follow parent links.
  const grants = new Set<string>();
  const visited = new Set<string>();
  for (const assigned of user.roles) {
    for (let name: string | undefined = assigned; name && !visited.has(name); name = directory[name]?.parent) {
      visited.add(name);
      for (const grant of directory[name]?.grants ?? []) grants.add(grant);
    }
  }
  return grants;
}
EOF
